                "SELECT id, batch_key, product_code, lot_number, produced_at, status FROM batch"
                        + " WHERE status NOT IN ('REJECTED', 'RECALLED') ORDER BY id",
                BATCH_MAPPER);
    }

    /** 按操作类型与命令键查询幂等命令记录。 */
    public Optional<CommandRow> findCommand(String operation, String commandKey) {
